const table = new Uint8Array(95 * 7);
for (let i = 0; i < table.length; i++) table[i] = parseInt(HEX.slice(i * 2, i * 2 + 2), 16);

/** Row bytes of a character; anything outside 0x20..0x7E draws as `?`. */
export function glyphRows(ch: string): Uint8Array {
  let code = ch.charCodeAt(0);
  if (!(code >= 0x20 && code <= 0x7e)) code = 0x3f;
  return table.subarray((code - 0x20) * 7, (code - 0x20) * 7 + 7);
}
